```

3. In the main asyncio loop, do as followed:

```
import streamlit.components.v1 as components
```

```
if st.session_state.should_close_system_expander:
    st.session_state.should_close_system_expander = False  # reset it
    components.html(
        f"""<script>
        let some_random_variable = `{get_current_time()}`;
        """
        + """
        function simulate(element, eventName) {
            var options = extend(defaultOptions, arguments[2] || {});
            var oEvent, eventType = null;

            for (var name in eventMatchers) {
                if (eventMatchers[name].test(eventName)) {
                eventType = name;
                break;
                }
            }

            if (!eventType)
                throw new SyntaxError('Only HTMLEvents and MouseEvents interfaces are supported');

            if (document.createEvent) {
                oEvent = document.createEvent(eventType);
                if (eventType == 'HTMLEvents') {
                oEvent.initEvent(eventName, options.bubbles, options.cancelable);
                } else {
                oEvent.initMouseEvent(eventName, options.bubbles, options.cancelable, document.defaultView,
                    options.button, options.pointerX, options.pointerY, options.pointerX, options.pointerY,
                    options.ctrlKey, options.altKey, options.shiftKey, options.metaKey, options.button, element);
                }
                element.dispatchEvent(oEvent);
            } else {
                options.clientX = options.pointerX;
                options.clientY = options.pointerY;
                var evt = document.createEventObject();
                oEvent = extend(evt, options);
                element.fireEvent('on' + eventName, oEvent);
            }
            return element;
        }

        function extend(destination, source) {
            for (var property in source)
                destination[property] = source[property];
            return destination;
        }

        var eventMatchers = {
            'HTMLEvents': /^(?:load|unload|abort|error|select|change|submit|reset|focus|blur|resize|scroll)$/,
            'MouseEvents': /^(?:click|dblclick|mouse(?:down|up|over|move|out))$/
        }
        var defaultOptions = {
            pointerX: 0,
            pointerY: 0,
            button: 0,
            ctrlKey: false,
            altKey: false,
            shiftKey: false,
            metaKey: false,
            bubbles: true,
            cancelable: true
        }
        let x = parent.document.querySelectorAll('svg[data-testid=stExpanderToggleIcon]')[0];
        console.log("*** stExpanderToggleIcon: " + (x ? "Found!": "Not found!"));
        if (x) {
            simulate(x, "click");
            console.log("*** stExpanderToggleIcon: Clicked!");
        } else {
            console.log("*** stExpanderToggleIcon: Can't Clicked!");
        }
        </script>"""
    )
```

The variable `some_random_variable` is important as I noticed that if the whole javascript is unchanged, it won't get executed the 2nd time and onward.

If there are more than one Expander, one may need to play with the Selector `document.querySelectorAll()` to pinpoint the right one.

The invokation of the Click Event is non-trivial. I tested a lot of methods (e.g. `x.onclick.call(x)`, `x.onclick.apply(x)`), but only the method used here can have the effect.

Although the post is about closing the Expander, opening it out should use the same trick.

## Update

This will be possible via the `st.column_config.ButtonColumn` in Streamlit 1.59+.

The values in the configured column become the button labels, and when a button is clicked Streamlit stores a one-shot click payload in `st.session_state[key]` with the clicked `row` and `label`.

For example:

```python
import pandas as pd
import streamlit as st

df = pd.DataFrame(
    {
        "name": ["Alice", "Bob", "Charlie"],
        "action": [":material/visibility: View"] * 3,
    }
)


def handle_view():
    click = st.session_state.view_click
    row = df.iloc[click["row"]]
    st.toast(f"Viewing {row['name']}")


st.dataframe(
    df,
    column_config={
        "action": st.column_config.ButtonColumn(
            "Action",
            type="tertiary",
            on_click=handle_view,
            key="view_click",
        )
    },
    hide_index=True,
)
```

You can also provide multiple actions per row by using a list of labels in the cell value:

```python
df = pd.DataFrame(
    {
        "name": ["Alice", "Bob", "Charlie"],
        "actions": [
            [":material/edit: Edit", ":material/delete: Delete"],
            [":material/edit: Edit", ":material/delete: Delete"],
            [":material/edit: Edit"],
        ],
    }
)


def handle_action():
    click = st.session_state.action_click
    row = df.iloc[click["row"]]

    if "Delete" in click["label"]:
        st.warning(f"Deleting {row['name']}")
    elif "Edit" in click["label"]:
        st.info(f"Editing {row['name']}")


st.dataframe(
    df,
    column_config={
        "actions": st.column_config.ButtonColumn(
            "Actions",
            on_click=handle_action,
            key="action_click",
        )
    },
    hide_index=True,
)
```

`ButtonColumn` also works in `st.data_editor`; the button cells are read-only, but clicks still trigger the callback.

